-- +goose Up
-- Журнал релизов. public_notes (пользовательский опыт) видно всем;
-- tech_notes (технические подробности) и comment — только админам, API
-- обычным пользователям их не отдаёт. status: released|planned|in_progress|
-- rolled_back|deprecated (по умолчанию released). notified_at — когда
-- отправлено уведомление админу (NULL = ещё нет). Историю seed-им из git.
CREATE TABLE releases (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    version TEXT NOT NULL UNIQUE,
    released_on DATE NOT NULL,
    title TEXT NOT NULL DEFAULT '',
    public_notes TEXT NOT NULL DEFAULT '',
    tech_notes TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT 'released',
    comment TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    notified_at TIMESTAMPTZ
);
CREATE INDEX releases_order_idx ON releases (released_on DESC, id DESC);

