INSERT INTO releases (version, released_on, title, public_notes, tech_notes, status, notified_at) VALUES
  ('2.13.0', '2026-07-16', 'новый бэкенд Go+Postgres, Vue-фронтенд, все мини-приложения', 'Полностью переписанное приложение: быстрый бэкенд и новый интерфейс, все мини-приложения на месте (Трекер, Чек-листы, Дневник, Метрики, Пароли, Напоминания, Ссылки, Статьи, Серверы, Конвертер, Помощь).', 'Tracker/Checker/Diary/Metrics/Passwords(E2E+sync)/Reminders/Links/Articles/
Servers/Converter/Help, доступы страниц, глобальный поиск, агент мониторинга,
деплой и бэкапы. Секреты вынесены из кода (.gitignore).', 'released', '2026-07-16'::date::timestamptz),
  ('2.14.0', '2026-07-17', 'Tracker v2 — стили отметок, мультицвет/мульти-эмодзи, счётчик, вся история, совместный доступ', 'Трекер стал гибче: разные стили отметок (квадраты/кружки/эмодзи) и счётчик, свой цвет и эмодзи у отметок, просмотр всей истории по месяцам и совместный доступ.', '- Виды трекера: отметки (квадратики/кружки/эмодзи) и счётчик (+1 клик, −1 долгое нажатие)
- Мультицвет и мульти-эмодзи: у отметок свой цвет/эмодзи, пикеры с палитрой и последними использованными, перекраска кликом
- Одноцветные: смена цвета категории перекрашивает старые отметки (цвет отметки NULL)
- Полноэкранная «Вся история» помесячно с самой старой отметки, из настроек
- Совместный доступ к трекеру: шаринг по id/@логину, бейдж 👥, участник отмечает и может покинуть, владелец отзывает
- Миграция 0015: kind/style/multi/emoji, color/emoji/count у отметок, tracker_shares', 'released', '2026-07-17'::date::timestamptz),
  ('2.15.0', '2026-07-17', 'страница Tasks — задачи с проектами, статусами, сроками и совместным доступом', 'Новая страница «Задачи»: проекты, статусы, сроки с напоминаниями, подзадачи-чеклисты, повторяющиеся задачи и совместный доступ.', '- Быстрое добавление, вкладки Сегодня/Планы/Все/Выполненные, ручной порядок
- Проекты: цвет, свои статусы (open/done/archived, любой порядок переключения), дефолты новых задач, свёртывание на сервере
- Карточка: приоритет (полоска), срок с временем, подзадачи-чеклист, описание Markdown, повтор (daily/weekly/monthly/интервал) с созданием следующего экземпляра
- Уведомления ботом: «подходит срок» (за N минут) и «просрочена» (воркер tasksnotify, тик 60 с)
- Совместные проекты: шаринг по id/@логину, исполнитель, участник может покинуть
- Интеграции: глобальный поиск, бейдж сегодня/просрочено на главной, PagesRegistry, Help
- Миграция 0016: task_projects, task_project_shares, tasks, task_checklist', 'released', '2026-07-17'::date::timestamptz),
  ('2.16.0', '2026-07-17', 'push-агент для домашних машин без внешнего IP + offline/online-уведомления ботом для всех серверов', 'Мониторинг домашних машин без внешнего IP и уведомления в бот, когда сервер уходит офлайн или возвращается онлайн.', 'push-агент для домашних машин без внешнего IP + offline/online-уведомления ботом для всех серверов', 'released', '2026-07-17'::date::timestamptz),
  ('2.17.0', '2026-07-17', 'Articles v2 (копирование, информация, публичное чтение, история-diff, позиция чтения, dbltap-редактирование, картинки), Reminders (категории, компактный режим, ежегодные, интервалы в днях/неделях/месяцах), Diary (сворачивание длинных записей)', 'Статьи: копирование, публичное чтение по ссылке, история изменений, запоминание позиции чтения и картинки. Напоминания: категории, компактный режим, ежегодные и гибкие интервалы. Дневник: длинные записи сворачиваются.', 'Articles v2 (копирование, информация, публичное чтение, история-diff, позиция чтения, dbltap-редактирование, картинки), Reminders (категории, компактный режим, ежегодные, интервалы в днях/неделях/месяцах), Diary (сворачивание длинных записей)', 'released', '2026-07-17'::date::timestamptz),
  ('2.18.0', '2026-07-18', 'My Files — доступ к папкам домашней машины (файловый агент, ro/rw, просмотр текста/картинок, стриминг музыки и видео с Range, загрузка/операции записи)', '«Мои файлы»: доступ к папкам домашней машины — просмотр текста и картинок, стриминг музыки и видео, загрузка и операции с файлами.', 'My Files — доступ к папкам домашней машины (файловый агент, ro/rw, просмотр текста/картинок, стриминг музыки и видео с Range, загрузка/операции записи)', 'released', '2026-07-18'::date::timestamptz),
  ('2.19.0', '2026-07-18', 'Help показывает только доступные страницы + настройка «стекло» карточек (полупрозрачность и размытие фона под карточками)', 'В «Помощи» видны только доступные вам страницы. Появилась настройка «стекло» для карточек — полупрозрачность и размытие фона под ними.', 'Help показывает только доступные страницы + настройка «стекло» карточек (полупрозрачность и размытие фона под карточками)', 'released', '2026-07-18'::date::timestamptz),
  ('2.20.0', '2026-07-18', 'Terminal — веб-консоль (shell) к домашней машине через PTY-агент и исходящий WS (xterm.js, спецклавиши для мобилки)', '«Терминал»: веб-консоль к домашней машине прямо из приложения, с удобными спецклавишами для телефона.', 'Terminal — веб-консоль (shell) к домашней машине через PTY-агент и исходящий WS (xterm.js, спецклавиши для мобилки)', 'released', '2026-07-18'::date::timestamptz),
  ('2.21.0', '2026-07-20', 'Checker — подгруппы и шаринг живой группы (⚙️, ссылка chg_/отправка), удаление шаблона из строки; Servers — компактный режим (совмещённый CPU+RAM без подписей, компактные диски) и пороговые уведомления по серверу (диск<N ГБ, RAM>N% дольше M мин, CPU>N% дольше M мин)', 'Чек-листы: подгруппы и шаринг живого списка по ссылке. Серверы: компактный режим и пороговые уведомления (по диску, памяти, процессору).', 'Checker — подгруппы и шаринг живой группы (⚙️, ссылка chg_/отправка), удаление шаблона из строки; Servers — компактный режим (совмещённый CPU+RAM без подписей, компактные диски) и пороговые уведомления по серверу (диск<N ГБ, RAM>N% дольше M мин, CPU>N% дольше M мин)', 'released', '2026-07-20'::date::timestamptz),
  ('2.22.0', '2026-07-20', 'Servers — пороги диска по каждому разделу отдельно (чекбокс + свой порог, чтобы не алертить /boot и т.п.); Checker — редактирование пункта по долгому нажатию (окно с правкой названия + Сохранить/Удалить)', 'Серверы: отдельные пороги свободного места для каждого раздела диска. Чек-листы: редактирование пункта по долгому нажатию.', 'Servers — пороги диска по каждому разделу отдельно (чекбокс + свой порог, чтобы не алертить /boot и т.п.); Checker — редактирование пункта по долгому нажатию (окно с правкой названия + Сохранить/Удалить)', 'released', '2026-07-20'::date::timestamptz),
  ('2.23.0', '2026-07-20', 'Checker — экспорт/импорт групп простым текстом и JSON (с подгруппами, автоопределение формата); Reminders — экспорт (текст/JSON), импорт (JSON) и шаринг категории (ссылка rem_ / отправка пользователю; kind=tracker пропускается)', 'Чек-листы: экспорт и импорт списков текстом и JSON. Напоминания: экспорт, импорт и шаринг категории.', 'Checker — экспорт/импорт групп простым текстом и JSON (с подгруппами, автоопределение формата); Reminders — экспорт (текст/JSON), импорт (JSON) и шаринг категории (ссылка rem_ / отправка пользователю; kind=tracker пропускается)', 'released', '2026-07-20'::date::timestamptz),
  ('2.24.0', '2026-07-21', 'Contacts — новая страница контактов (примечание, фото, галочка «принимать сразу») + входящие шаринги: все send-потоки (Checker/Reminders/Articles/Tracker/Tasks) идут через подтверждение, от доверенных контактов — мгновенно', 'Новая страница «Контакты» (заметки, фото, автоприём). Все входящие «поделиться» идут через подтверждение, а от доверенных контактов — сразу.', 'Contacts — новая страница контактов (примечание, фото, галочка «принимать сразу») + входящие шаринги: все send-потоки (Checker/Reminders/Articles/Tracker/Tasks) идут через подтверждение, от доверенных контактов — мгновенно', 'released', '2026-07-21'::date::timestamptz),
  ('2.25.0', '2026-07-21', 'Contacts — внешние контакты (люди, которых ещё нет в боте: бейдж «не в боте», по id — данные через Bot API getChat, автопривязка при первом входе человека) + галерея фото контакта (до 20, лайтбокс, мультизагрузка)', 'Контакты: можно добавлять людей, которых ещё нет в боте, и галерея фото контакта с лайтбоксом.', 'Contacts — внешние контакты (люди, которых ещё нет в боте: бейдж «не в боте», по id — данные через Bot API getChat, автопривязка при первом входе человека) + галерея фото контакта (до 20, лайтбокс, мультизагрузка)', 'released', '2026-07-21'::date::timestamptz),
  ('2.25.1', '2026-07-21', 'Tasks — «Проект» переименован в «Категория» во всём UI (вкладки, карточка, настройки, шаринг, Help, Contacts, сообщения бота, глобальный поиск); фронтенд-сущности TaskProject→TaskCategory, ProjectSettingsModal→CategorySettingsModal; wire-формат API и схема БД без изменений', 'В «Задачах» «Проект» переименован в «Категорию» по всему интерфейсу.', 'Tasks — «Проект» переименован в «Категория» во всём UI (вкладки, карточка, настройки, шаринг, Help, Contacts, сообщения бота, глобальный поиск); фронтенд-сущности TaskProject→TaskCategory, ProjectSettingsModal→CategorySettingsModal; wire-формат API и схема БД без изменений', 'released', '2026-07-21'::date::timestamptz),
  ('2.26.0', '2026-07-21', 'Projects — новая страница проектов-сборников: блоки (текст/rich text, картинки с лайтбоксом и pinch-zoom, файлы, гео) + живые ref-блоки (чек-листы, статьи-спойлеры, задачи и категории задач; создание новых с появлением на своих страницах), вставка между блоками и разбиение текста, фон блока, категории проектов, ленивые сворачиваемые карточки с автообновлением, параметры (тип/статус/теги/даты/tz/обложка), совместное редактирование через deliverShare, история изменений и ★ «изменён другим»', 'Новая страница «Проекты»: собирайте заметки из блоков — текст, картинки, файлы, гео, а также живые чек-листы, статьи и задачи; категории, обложки, совместное редактирование и история изменений.', 'Projects — новая страница проектов-сборников: блоки (текст/rich text, картинки с лайтбоксом и pinch-zoom, файлы, гео) + живые ref-блоки (чек-листы, статьи-спойлеры, задачи и категории задач; создание новых с появлением на своих страницах), вставка между блоками и разбиение текста, фон блока, категории проектов, ленивые сворачиваемые карточки с автообновлением, параметры (тип/статус/теги/даты/tz/обложка), совместное редактирование через deliverShare, история изменений и ★ «изменён другим»', 'released', '2026-07-21'::date::timestamptz),
  ('2.27.0', '2026-07-21', 'Projects — фикс отображения картинок (URL с учётом /app/habits/), кнопка «＋ Блок» сверху для вставки в начало; типы пользователей (regular/VIP/payed1/payed2, назначаются админом в карточке пользователя) и лимиты Projects по типам (блоки на проект — по умолчанию 100, картинки/файлы на пользователя, размеры картинки/файла) с редактором в админке и учётом загрузок', 'Проекты: исправлено отображение картинок и добавлена кнопка вставки блока в начало. Введены типы пользователей и лимиты для «Проектов».', 'Projects — фикс отображения картинок (URL с учётом /app/habits/), кнопка «＋ Блок» сверху для вставки в начало; типы пользователей (regular/VIP/payed1/payed2, назначаются админом в карточке пользователя) и лимиты Projects по типам (блоки на проект — по умолчанию 100, картинки/файлы на пользователя, размеры картинки/файла) с редактором в админке и учётом загрузок', 'released', '2026-07-21'::date::timestamptz),
  ('2.27.1', '2026-07-21', 'Servers — фикс раскладки чекбоксов в настройках сервера (общий width:100% для input растягивал чекбоксы, текст сжимался в узкую колонку); поле порога ГБ у дисков приведено к компактному виду', 'Серверы: исправлена раскладка настроек (чекбоксы и поля порогов).', 'Servers — фикс раскладки чекбоксов в настройках сервера (общий width:100% для input растягивал чекбоксы, текст сжимался в узкую колонку); поле порога ГБ у дисков приведено к компактному виду', 'released', '2026-07-21'::date::timestamptz),
  ('2.27.2', '2026-07-21', 'Links/Articles — подложка у категорий верхнего уровня (карточка var(--card-color), как группы на остальных страницах; при включённой полупрозрачности/размытии фона участвует в card-glass)', 'Ссылки и Статьи: у категорий верхнего уровня появилась карточка-подложка, как на других страницах.', 'Links/Articles — подложка у категорий верхнего уровня (карточка var(--card-color), как группы на остальных страницах; при включённой полупрозрачности/размытии фона участвует в card-glass)', 'released', '2026-07-21'::date::timestamptz),
  ('2.27.3', '2026-07-21', 'Checker — поле нового пункта стало авто-растущим (textarea в одну строку, растёт вниз при длинном тексте, Enter добавляет); Settings — блок «Пользователи» в админке сворачивается (по умолчанию свёрнут)', 'Чек-листы: поле нового пункта растёт под длинный текст. Настройки: блок «Пользователи» в админке сворачивается.', 'Checker — поле нового пункта стало авто-растущим (textarea в одну строку, растёт вниз при длинном тексте, Enter добавляет); Settings — блок «Пользователи» в админке сворачивается (по умолчанию свёрнут)', 'released', '2026-07-21'::date::timestamptz),
  ('2.28.0', '2026-07-21', 'Food — новая страница дневника питания: 4 вкладки (Дневник/Общие/Рецепты/Статистика, активная в ?tab=); дневник по дням со сводкой и прогресс-барами КБЖУ (превышение — красным и текстом), приёмы пищи группами (завтрак/обед/ужин/перекусы/без категории) с фото, временем и составом; каталог продуктов (КБЖУ на 100 г/мл, вес шт/порции, поиск с недавними первыми, архив вместо удаления использованных); снимки КБЖУ в истории — изменение продукта/шаблона/рецепта не меняет старые записи; профиль питания с onboarding и расчётом целей по Mifflin–St Jeor (активность/цель/белок г/кг от выбранной базы, ручное переопределение), цели периодами; шаблоны и рецепты (КБЖУ на 100 г и порцию, добавление в дневник по весу/порциям, создание из записи); шаринг дневника read-only через deliverShare (kind food) с флагами цели/фото/описания/вес; статистика за 7/14/30 дней/период с карточками и SVG-графиками + слой /food/metrics/{key} для будущей интеграции с Metrics; фото до 10 МБ с refcount-очисткой; unit-тесты расчётов', 'Новая страница «Еда»: дневник питания с КБЖУ и прогресс-барами, приёмы пищи с фото, каталог продуктов, шаблоны и рецепты, цели по формуле, шаринг дневника и статистика с графиками.', 'Food — новая страница дневника питания: 4 вкладки (Дневник/Общие/Рецепты/Статистика, активная в ?tab=); дневник по дням со сводкой и прогресс-барами КБЖУ (превышение — красным и текстом), приёмы пищи группами (завтрак/обед/ужин/перекусы/без категории) с фото, временем и составом; каталог продуктов (КБЖУ на 100 г/мл, вес шт/порции, поиск с недавними первыми, архив вместо удаления использованных); снимки КБЖУ в истории — изменение продукта/шаблона/рецепта не меняет старые записи; профиль питания с onboarding и расчётом целей по Mifflin–St Jeor (активность/цель/белок г/кг от выбранной базы, ручное переопределение), цели периодами; шаблоны и рецепты (КБЖУ на 100 г и порцию, добавление в дневник по весу/порциям, создание из записи); шаринг дневника read-only через deliverShare (kind food) с флагами цели/фото/описания/вес; статистика за 7/14/30 дней/период с карточками и SVG-графиками + слой /food/metrics/{key} для будущей интеграции с Metrics; фото до 10 МБ с refcount-очисткой; unit-тесты расчётов', 'released', '2026-07-21'::date::timestamptz),
  ('2.29.0', '2026-07-22', 'Автоматизация — новая страница (personal, доступ не всем) для автоматизированных действий по расписанию/вручную; первый тип — заказ воды на jur.am', 'Новая страница «Автоматизация»: действия по расписанию или вручную. Первый сценарий — заказ воды на jur.am.', 'Исполнитель internal/jurwater проходит весь сценарий Magento 2 обычными HTTP-запросами без headless-браузера: логин → корзина (N бутылей «Макур Джур 19л») → долг возвратной тары из CRM → адрес и время доставки (mp_delivery_date/time, ближайшая доступная дата и первый слот) → возвратная тара (checkoutjur/quote/index) → оформление наличными (payment-information); в dry-run последний шаг пропускается. Карточка: логин/пароль сайта (AES-256-GCM, ключ AUTOMATION_KEY или производный от BOT_TOKEN; наружу только маскированный логин + has_creds), количество, тара auto(из CRM)/fixed, слот времени, оплата, интервал повтора и next_run_at. Планировщик internal/automation (тик 1 мин): уведомления в бот за сутки и за час до запуска (можно остановить), запуск по сроку со сдвигом счётчика на +interval_days; ручной запуск и пробный прогон через тот же Execute (лок running), результат — в историю automation_runs с пошаговым логом и уведомлением. Проверено dry-run против живого jur.am (логин→14 бутылей→время→тара 14 из CRM→стоп перед заказом), уведомление за сутки, guard personal-страницы (403 не-админу), unit-тесты шифрования и логики дат', 'released', '2026-07-22'::date::timestamptz),
  ('2.29.1', '2026-07-22', 'Автоматизация — сетевой выход через домашний агент (обход Cloudflare)', 'Автоматизация: сетевой выход через домашний агент (обход блокировок).', 'jur.am за Cloudflare отдаёт датацентр-IP прод-сервера 403 (даже главную, с любым UA), поэтому запуск с сервера падал на первом шаге. Решение: HTTP-запросы к jur.am туннелируются через агента на домашней машине (резидентный IP проходит), вся логика сценария остаётся на проде.

- internal/egress — хаб per-user WS + http.RoundTripper, туннелирующий запросы агента; cookie-jar/редиректы jurwater работают прозрачно поверх туннеля
- jurwater.Params.Transport — inject релей-транспорта (nil = прямой выход для локальных тестов)
- automation-agent (public repo habits-agent, subdir + install-automation.sh + релиз automation-v1.0.0) — тонкий форвардер, держит исходящий WS, выполняет запросы только к белому списку (jur.am), без своих cookie и без follow-redirect
- WS GET /automation/agent (Bearer из automation_agents, вне tma-auth); GET /automation/agent-info (токен+команда+online), POST /automation/agent-token/regenerate
- Execute требует онлайн-агента (иначе «агент не в сети»); воркер при офлайне откладывает на час с предупреждением; фикс: неуспешный запуск по расписанию переносится на +1ч (а не крутится каждый тик), успех — на +interval
- фронтенд: панель статуса агента (онлайн/оффлайн, токен, команда установки, regen)

Проверено локально end-to-end: сервер + агент (эта машина, резидентный IP) → dry-run туннелирует все 6 шагов к jur.am (200), офлайн-агент даёт понятную ошибку; агент установлен на resager-tuf как user-systemd против прода (online подтверждён)', 'released', '2026-07-22'::date::timestamptz),
  ('2.29.2', '2026-07-22', 'Автоматизация — фикс очистки корзины (баг «в корзине 28/42»)', 'Автоматизация: исправлена очистка корзины.', 'clearCart слал GET /rest/carts/mine/items и DELETE без заголовка X-Requested-With, из-за чего Magento отвечал 401 (session-авторизация REST-эндпоинтов mine требует этот заголовок против CSRF). Корзина не чистилась → остаток прошлых прогонов суммировался с новыми 14 (28, 42…). Добавлен X-Requested-With (+ User-Agent) на GET и DELETE очистки, проверка кода ответа. Проверено: поверх остатка 28 clearCart вычищает всё и оставляет ровно 14 (GET items→200, DELETE→200, dry-run зелёный)', 'released', '2026-07-22'::date::timestamptz),
  ('2.30.0', '2026-07-22', 'Links — отправить папку пользователю (копия поддерева через deliverShare)', 'Ссылки: можно отправить целую папку другому пользователю.', 'Помимо прежнего «поделиться текстом в буфер» у папки Links добавлена отправка
пользователю приложения, как в других разделах: получатель получает копию
поддерева (папка + вложенные папки + ссылки) через общий механизм deliverShare
(kind links_folder, POST /links/folders/{id}/share {to}) — сразу при auto_accept,
иначе во «Входящие» на странице Contacts. Только серверное хранилище (у папки
должен быть серверный id). Бэкенд: CopyLinkFolderTo (транзакционный рекурсивный
копир поддерева), ShareTitle/ApplyShare/shareKindMsg + links_folder, sendFolder-
хендлер. Фронт: секция «Отправить пользователю» в модалке папки (видна в
серверном режиме) + shareFolderToUser.', 'released', '2026-07-22'::date::timestamptz),
  ('2.31.0', '2026-07-22', 'Links — попап «Поделиться» как в Checker (по id, ссылка-приглашение, копия в буфер) для папок и ссылок', 'Ссылки: попап «Поделиться» как в чек-листах — по id, ссылкой-приглашением или копией в буфер, для папок и ссылок.', 'У папки и у отдельной ссылки кнопка 📤 открывает единый экран-попап с тремя
способами: отправить пользователю по id/@логину (копия через deliverShare —
папка kind links_folder, ссылка kind link), ссылка-приглашение
t.me/<bot>?startapp=lnf_<token>/lnk_<token> (redeem копирует получателю), и
прежнее «копировать в буфер» (папка — списком, ссылка — URL). Отправка по id и
ссылка-приглашение — только серверное хранилище.

БД: миграция 0033 — share_token на links_folders и links. Бэкенд: CopyLinkTo,
Ensure*/Redeem* токенов, kind link в ShareTitle/ApplyShare/shareKindMsg,
хендлеры share-token/redeem/sendLink + маршруты. Фронт: RecipientPicker в
попапах, api folderShareToken/linkShareToken/shareLinkToUser, redeem.ts —
префиксы lnf_/lnk_, кнопки 📤 в LinkRow и модалках.', 'released', '2026-07-22'::date::timestamptz),
  ('2.32.0', '2026-07-22', 'Checker — вложенность подгрупп любой глубины, подгруппы без подложки, поиск по группам и пунктам', 'Чек-листы: подгруппы любой глубины и поиск по группам и пунктам.', '- Подгруппы теперь любой глубины (было — один уровень): CreateCheckGroup
  принимает родителя на любом уровне; снимок/копия/redeem (copyGroupTree),
  импорт (ImportCheckGroup) и раскрытие чек-листа в Projects (resolveCheckerGroup)
  переведены на рекурсию; лимит глубины при импорте (checkerMaxDepth=20).
  Фронт: CheckGroupCard рекурсивно рендерит поддерево, удаление уносит весь
  подтри локально, добавить подгруппу можно из настроек любой группы.
- Убрана непрозрачная подложка у подгрупп: только левая линия-акцент и отступ,
  фон родителя-карточки (в т.ч. «стекло») просвечивает.
- Поиск: глобальное поле на странице (по именам групп и пунктам, включая
  подгруппы любой глубины) + локальный 🔍 у каждой группы с подгруппами
  (search.ts: groupRelevant/visibleItems). При поиске карточки раскрываются,
  показываются только совпавшие пункты/ветки.
- Экспорт/импорт текста: глубина подгрупп кодируется числом «#» (#/##/###…),
  JSON — рекурсивные subgroups (transfer.ts). Projects: рекурсивный CheckerGroupView.', 'released', '2026-07-22'::date::timestamptz),
  ('2.32.1', '2026-07-22', 'Checker — единый предел вложенности 20 уровней (включая ручной ввод) + справка', 'Чек-листы: единый предел вложенности 20 уровней и справка.', 'Раньше предел глубины стоял только на импорте и на раскрытии в Projects, а ручное
создание подгрупп было неограниченным. Теперь единый предел store.MaxCheckerDepth=20
(группа верхнего уровня = 1-й уровень) во всех путях:
- CreateCheckGroup считает глубину родителя рекурсивным CTE и возвращает ErrTooDeep
  → 409 too_deep, если новая подгруппа вышла бы за 20 уровней;
- импорт и resolveCheckerGroup (Projects) используют ту же константу;
- в UI кнопка «➕ Подгруппа» скрывается на 20-м уровне с подсказкой, ошибка
  too_deep обрабатывается тостом.
Справка на странице Help дополнена: вложенность до 20 уровней и как работает поиск.', 'released', '2026-07-22'::date::timestamptz),
  ('2.33.0', '2026-07-22', 'Checker — счётчик done/total всегда у заголовка, «скрывать выполненное», подсветка при поиске', 'Чек-листы: счётчик выполнено/всего у заголовка, «скрывать выполненное» и подсветка совпадений при поиске.', '- Счётчик «сделано/всего» показывается у заголовка группы всегда (раньше — только
  в свёрнутом виде); считает прямые пункты группы.
- Настройка группы «Скрывать выполненное» (миграция 0034: hide_done на
  checker_groups; PATCH /checker/groups/{id} принимает name/hide_done через
  UpdateCheckGroup): выполненные пункты не показываются в списке, но учитываются
  в счётчике. RenameCheckGroup → UpdateCheckGroup (COALESCE, частичный патч).
- Подсветка совпадений при поиске: highlightParts режет текст на сегменты
  <span class="hit"> (имена групп и пунктов), без v-html — пользовательский
  текст не эскейпится через innerHTML.', 'released', '2026-07-22'::date::timestamptz),
  ('2.33.1', '2026-07-22', 'Автоматизация — фикс «нет ошибок, но и заказа нет» + диагностика шагов jur.am', 'Автоматизация: исправлен случай «нет ошибок, но заказ не создаётся» и добавлена диагностика шагов.', 'Шаг оформления заказа раньше считал успехом ЛЮБОЙ ответ HTTP 200 и возвращал сырое
тело как «номер заказа». Кастомный чекаут jur.am при неудаче отдаёт 200 с не-числовым
телом (null/ошибка) — заказ не создавался, но шаг был «✓ Заказ оформлен». Теперь успех
только при числовом id заказа (Magento отдаёт голый id); иначе шаг падает с сырым
ответом сайта (безопасно для повтора — заказ не создан, дубля не будет).
Шаг «сессия»: при отсутствии form_key различает Cloudflare-challenge/403 от прочего
(по HTTP-коду и телу) — вместо глухого «не найден form_key» понятная причина.
getStatus отдаёт HTTP-код; добавлены unit-тесты валидации номера заказа.

Диагностика прод-логов: реального успешного заказа не было ни разу; последний боевой
запуск падал на шаге «сессия» (Cloudflare), до оформления не доходил.', 'released', '2026-07-22'::date::timestamptz),
  ('2.34.0', '2026-07-23', 'модалки прокручиваются по высоте + перенос пункта Checker между группами', 'Высокие окна настроек теперь прокручиваются. В чек-листах можно перенести пункт между группами.', '- Глобально: .modal-content (theme.css) получил max-height 100dvh−24px (фолбэк vh)
  и overflow-y:auto — высокие окна настроек (в т.ч. настройки категории Tracker)
  прокручиваются, а не уходят за экран. Проверено: в модалках нет всплывашек,
  которые обрезались бы overflow.
- Checker: в окне пункта (долгое нажатие) добавлен выбор «Группа» — перенос пункта
  в любую другую группу (список с отступом по вложенности). Бэкенд: MoveCheckItem
  (перенос в конец целевой группы с проверкой владения обеими группами), group_id
  в PATCH /checker/items/{id} (комбинируется с name). Фронт: select в модалке,
  локальный перенос объекта пункта между реактивными списками групп.', 'released', '2026-07-23'::date::timestamptz),
  ('2.34.1', '2026-07-23', 'Checker — в переносе пункта подгруппы показаны полным путём с родителем', 'Чек-листы: при переносе пункта подгруппы показаны полным путём с родителем.', 'Список групп в окне пункта строится полным путём «Родитель › Подгруппа» (DFS —
подгруппы идут сразу под родителем), чтобы подгруппа была однозначна и в
свёрнутом select. Раньше — только имя с отступом em-space (в закрытом списке
контекст родителя терялся).', 'released', '2026-07-23'::date::timestamptz),
  ('2.35.0', '2026-07-24', 'Checker — прогресс-бар, массовые действия, видимая ✏️ и заметка у пункта', 'Чек-листы: прогресс-бар, массовые действия, видимая кнопка ✏️ и заметка у пункта.', 'Phase 1 из крупного обновления Checker:
- Прогресс-бар у заголовка группы (по прямым пунктам) + «Σ done/total» по всему
  поддереву, если есть подгруппы.
- Массовые действия в настройках группы: отметить все / снять все / удалить
  выполненные (POST /checker/groups/{id}/items/bulk → BulkSetItemsDone/DeleteDoneItems).
- Видимая кнопка ✏️ на пункте (открывает то же окно, что и долгое нажатие).
- Заметка/описание у пункта: миграция 0035 (note на checker_items ≤4000),
  поле в окне пункта, показ под названием.
- Мелочь: хендлер renameGroup → updateGroup (по факту меняет name+hide_done).', 'released', '2026-07-24'::date::timestamptz),
  ('2.36.0', '2026-07-24', 'Checker Phase 2 — смена родителя группы, drag-and-drop за заголовок, дублирование', 'Чек-листы: смена родителя группы, перетаскивание за заголовок и дублирование.', '- Смена родителя группы: select «Родитель» в настройках (🏠 верхний уровень + все
  группы полным путём, кроме самой группы и её поддерева). Бэкенд MoveCheckGroup:
  проверка цикла (нельзя в своё поддерево → 409 conflict) и предела глубины
  (глубина нового родителя + высота поддерева ≤ 20 → too_deep). POST .../{id}/move.
- Drag-and-drop групп за заголовок среди соседей (useGroupReorder, pointer-события,
  touch-action:none на заголовке, порог 8px, живая сортировка мутацией position),
  сохранение порядка POST /checker/groups/reorder (ReorderCheckGroups).
- Дублирование группы со всем поддеревом, сохраняя done+note (DuplicateCheckGroup,
  groupFullSnapshot/createGroupNodeFull), имя «<name> (копия)». POST .../{id}/duplicate.
- topGroups/children теперь сортируются по position.', 'released', '2026-07-24'::date::timestamptz),
  ('2.37.0', '2026-07-24', 'Checker Phase 3 — корзина (мягкое удаление, отмена, срок хранения)', 'Чек-листы: корзина с мягким удалением, отменой и сроком хранения.', '- Удаление группы теперь мягкое: SoftDeleteCheckGroup ставит deleted_at на группу
  и всё поддерево (миграция 0036, checker_groups.deleted_at + user_settings.checker_trash_days).
  Все чтения групп исключают deleted_at (список, копия/шаринг/токен, resolve в Projects,
  move/reorder/duplicate, ShareTitle).
- Отмена: баннер «…в корзине · Отменить» сразу после удаления (POST .../{id}/restore).
- Корзина (кнопка внизу, GET /checker/trash): список удалённых корней с агрегатами
  (групп/пунктов в поддереве + когда удалено), восстановление, удаление навсегда
  (DELETE /checker/trash/{id}, каскад), очистка (DELETE /checker/trash), срок хранения
